package orders

// GetByUser 按用户查订单（PR 新增）
func (s *Store) GetByUser(userID string) ([]Order, error) {
    q := "SELECT * FROM orders WHERE user_id = '" + userID + "'"
    rows, err := s.db.Query(q)
    if err != nil {
        return nil, err
    }
    defer rows.Close()
    return scanOrders(rows)
}
